/* Black and gold skins 78 to 89, drawn from the supplied artwork (background removed, one sprite sheet of 12 icons).
   They take the slots just below the Warden skins. In the world the icon sits on the character like a helmet crest. */
const GOLD_IMG=(()=>{const i=new Image();i.src='data:image/webp;base64,';return i})();
const GOLD_RECT=[[4, 6, 128, 123], [140, 6, 128, 123], [278, 4, 123, 128], [4, 141, 128, 125], [140, 163, 128, 81], [288, 140, 104, 128], [4, 282, 128, 115], [140, 293, 128, 94], [276, 286, 128, 108], [4, 412, 128, 127], [140, 412, 127, 128], [276, 412, 128, 127]];
[["Gilded Oni", "bat"], ["Spike Sentinel", "star"], ["Crowned Warlord", "hex"], ["Skull Pilot", "round"], ["Golden Hawk", "delta"], ["Onyx Serpent", "drop"], ["Gilded Ape", "cloud"], ["Hazard Wing", "diamond"], ["Cracked Titan", "ram"], ["Toxic Trooper", "clover"], ["Royal Seal", "sun"], ["Golden Scarab", "cross"]].forEach((d,i)=>{
  Object.assign(SKINS[78+i],{name:d[0],rarity:3,src:i%3===1?'sub':'shop',tier:0,body:'#17130d',dark:'#080705',accent:'#e0a526',pat:5,head:'#17130d',hat:0,helm:0,
    gold:GOLD_RECT[i],chute:{c1:'#17130d',c2:'#e0a526',pat:2,sh:d[1]}});
});
function drawGoldHead(c,sk,r,o){
  if(!GOLD_IMG.complete||!GOLD_IMG.naturalWidth)return false;
  const g=sk.gold,k=r*2.45/128,dw=g[2]*k,dh=g[3]*k;
  c.save();c.translate(r*.06,0);c.rotate(o&&o.pv?Math.PI/2:-Math.PI/2);   /* previews keep the icon upright; in the world it is turned 180 degrees */
  c.imageSmoothingEnabled=true;c.imageSmoothingQuality='high';
  c.drawImage(GOLD_IMG,g[0],g[1],g[2],g[3],-dw/2,-dh/2,dw,dh);
  if(o&&o.flash){c.globalAlpha=.55;c.fillStyle='#ffffff';c.beginPath();c.arc(0,0,r*.7,0,Math.PI*2);c.fill()}
  c.restore();return true;
}
